        entry = self.fixtures.get(path)
        if entry is None:
            raise RuntimeError(
                f"fixture manifest has no response for {path}; evidence unavailable"
            )
        status = entry.get("status")
        if status != 200:
            raise RuntimeError(f"fixture for {path} has HTTP status {status}")
